function startOfDay(date){const day=new Date(date);day.setHours(0,0,0,0);return day;}
function addDays(date,count){const day=new Date(date);day.setDate(day.getDate()+count);return day;}
function weekDays(date){const start=addDays(startOfDay(date),-date.getDay());return Array.from({length:7},(_,index)=>addDays(start,index));}
function parseClockMinutes(text){const match=/^(\d{1,2}):(\d{2})\s*([AP]M)?$/i.exec(String(text||'').trim());if(!match)return null;let hour=+match[1];if(match[3]){hour%=12;if(match[3].toUpperCase()==='PM')hour+=12;}return hour*60+ +match[2];}
function formatHour(hour){return new Date(2000,0,1,hour%24).toLocaleTimeString('en-US',{hour:'numeric'});}
function calendarEvents(){const clientId=$('#calendar-client')?.value||'',status=$('#calendar-status')?.value||'',clientName=clients.find(client=>client.id===clientId)?.name;const posts=allPosts().map(post=>({date:post.date,minutes:parseClockMinutes(post.time)??540,time:post.time,title:post.title,client:post.client,channel:post.channel,status:post.status,cls:post.cls||'event-purple',autopilot:false}));const autopilot=autopilotCalendarEvents().map(event=>({...event,status:event.status==='in_review'?'In Review':'Scheduled'}));return[...posts,...autopilot].filter(event=>(!clientName||event.client===clientName)&&(!status||(status==='autopilot'?event.autopilot:event.status===status)));}
function renderCalendarFilters(){const select=$('#calendar-client');if(!select)return;const current=select.value;select.innerHTML='<option value="">All clients</option>'+clients.map(client=>`<option value="${escapeHtml(client.id)}">${escapeHtml(client.name)}</option>`).join('');if(clients.some(client=>client.id===current))select.value=current;}
function calendarLabel(){if(calView==='month')return calCursor.toLocaleDateString('en-US',{month:'long',year:'numeric'});if(calView==='day')return calCursor.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});const days=weekDays(calCursor),first=days[0],last=days[6],sameMonth=first.getMonth()===last.getMonth();return `${first.toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${last.toLocaleDateString('en-US',sameMonth?{day:'numeric'}:{month:'short',day:'numeric'})}, ${last.getFullYear()}`;}
function renderCalendar(){const grid=$('#calendar-grid'),timeline=$('#calendar-timeline');if(!grid||!timeline)return;renderCalendarFilters();$$('[data-cal-view]').forEach(button=>{const active=button.dataset.calView===calView;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));});$('#calendar-month').textContent=calendarLabel();$('#prev-month').setAttribute('aria-label',`Previous ${calView}`);$('#next-month').setAttribute('aria-label',`Next ${calView}`);grid.hidden=calView!=='month';timeline.hidden=calView==='month';if(calView==='month')renderMonth();else renderTimeline(calView==='day'?[calCursor]:weekDays(calCursor));renderBestTimesNote();}
function renderMonth(){const grid=$('#calendar-grid'),year=calCursor.getFullYear(),month=calCursor.getMonth(),names=['SUN','MON','TUE','WED','THU','FRI','SAT'],first=new Date(year,month,1).getDay(),today=localIsoDate(new Date()),events=calendarEvents();grid.innerHTML=names.map(name=>`<div class="calendar-day day-name">${name}</div>`).join('');for(let i=0;i<42;i++){const cell=new Date(year,month,i-first+1),iso=localIsoDate(cell),other=cell.getMonth()!==month,ev=events.filter(event=>event.date===iso).sort((a,b)=>a.minutes-b.minutes);grid.insertAdjacentHTML('beforeend',`<div class="calendar-day ${iso===today?'today':''}" style="${other?'opacity:.42':''}"><button type="button" class="day-num" data-open-day="${iso}" aria-label="Open ${cell.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}">${cell.getDate()}</button>${ev.slice(0,2).map(event=>`<div class="calendar-event ${event.cls}" title="${escapeHtml(`${event.time} · ${event.autopilot?'Autopilot · ':''}${event.status} · ${event.title}`)}">${event.autopilot?'⚡ ':''}${escapeHtml(event.client.split(' ')[0])}: ${escapeHtml(event.title)}</div>`).join('')}${ev.length>2?`<button type="button" class="more-events" data-open-day="${iso}">+${ev.length-2} more</button>`:''}</div>`);}}
function layoutDayEvents(list,duration=EVENT_MINUTES){const sorted=[...list].sort((a,b)=>a.minutes-b.minutes),placed=[];let cluster=[],clusterEnd=-1;const flush=()=>{const lanes=[];cluster.forEach(event=>{let lane=lanes.findIndex(end=>end<=event.minutes);if(lane===-1){lane=lanes.length;lanes.push(0);}lanes[lane]=event.minutes+duration;event.lane=lane;});cluster.forEach(event=>{event.lanes=lanes.length;});placed.push(...cluster);cluster=[];clusterEnd=-1;};sorted.forEach(event=>{if(cluster.length&&event.minutes>=clusterEnd)flush();cluster.push({...event});clusterEnd=Math.max(clusterEnd,event.minutes+duration);});if(cluster.length)flush();return placed;}
function renderTimeline(days){const timeline=$('#calendar-timeline'),events=calendarEvents(),todayIso=localIsoDate(new Date()),now=new Date(),columns=`56px repeat(${days.length},minmax(0,1fr))`,key=`${calView}:${localIsoDate(days[0])}`,previousScroll=$('#timeline-scroll')?.scrollTop,single=days.length===1,duration=single?60:EVENT_MINUTES;const dayHtml=days.map(day=>{const iso=localIsoDate(day),bands=(bestTimes.windows[day.getDay()]||[]).map(window=>`<div class="best-time-band ${bestTimes.enough?'':'starter'}" style="top:${window.start*HOUR_HEIGHT}px;height:${(window.end-window.start)*HOUR_HEIGHT}px" title="${escapeHtml(bestTimes.enough?`Best time: ${formatHour(window.start)}–${formatHour(window.end)} · ${window.lift}× your average engagement rate across ${window.posts} post${window.posts===1?'':'s'}`:`Starter window: ${formatHour(window.start)}–${formatHour(window.end)}. Replaced by your own best times once there's enough post history.`)}"><span>${bestTimes.enough?'Best time':'Starter window'}</span></div>`).join(''),dayEvents=layoutDayEvents(events.filter(event=>event.date===iso),duration).map(event=>`<div class="timeline-event calendar-event ${event.cls}" style="top:${event.minutes/60*HOUR_HEIGHT+1}px;height:${duration/60*HOUR_HEIGHT-3}px;left:calc(${event.lane/event.lanes*100}% + 3px);width:calc(${100/event.lanes}% - 6px)" title="${escapeHtml(`${event.time} · ${event.client} · ${event.channel} · ${event.autopilot?'Autopilot · ':''}${event.status}\n${event.title}`)}"><b>${escapeHtml(event.time)}${event.autopilot?' ⚡':''}</b><span>${escapeHtml(single?`${event.client} · ${event.title}`:`${event.client.split(' ')[0]}: ${event.title}`)}</span>${single?`<small>${escapeHtml(event.channel)} · ${escapeHtml(event.status)}</small>`:''}</div>`).join(''),nowLine=iso===todayIso?`<div class="timeline-now" style="top:${(now.getHours()*60+now.getMinutes())/60*HOUR_HEIGHT}px" aria-hidden="true"></div>`:'';return `<div class="timeline-col ${iso===todayIso?'today':''}" data-date="${iso}" role="group" aria-label="${escapeHtml(day.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}))}">${bands}${dayEvents}${nowLine}</div>`;}).join('');timeline.innerHTML=`<div class="timeline-frame ${single?'single-day':''}"><div class="timeline-head" style="grid-template-columns:${columns}"><div></div>${days.map(day=>{const iso=localIsoDate(day);return `<button type="button" class="timeline-day-head ${iso===todayIso?'today':''}" data-open-day="${iso}" ${single?'disabled':''}><span>${day.toLocaleDateString('en-US',{weekday:'short'}).toUpperCase()}</span><b>${day.getDate()}</b></button>`;}).join('')}</div><div class="timeline-scroll" id="timeline-scroll"><div class="timeline-body" style="grid-template-columns:${columns};height:${24*HOUR_HEIGHT}px"><div class="timeline-hours">${Array.from({length:24},(_,hour)=>`<span style="top:${hour*HOUR_HEIGHT}px">${hour?formatHour(hour):''}</span>`).join('')}</div>${dayHtml}</div></div></div>`;const scroll=$('#timeline-scroll');if(!timeline.getClientRects().length){timelineKey=null;return;}if(key===timelineKey&&previousScroll!==undefined){scroll.scrollTop=previousScroll;return;}timelineKey=key;const visible=events.filter(event=>days.some(day=>localIsoDate(day)===event.date)),firstHour=visible.length?Math.floor(Math.min(...visible.map(event=>event.minutes))/60):8;scroll.scrollTop=Math.max(0,Math.max(0,Math.min(7,firstHour-1))*HOUR_HEIGHT-10);}
// Best times: engagement rate by weekday and hour from published posts in weekly reports,
// smoothed toward the overall average so one lucky post doesn't define a window.
function computeBestTimes(points){const scored=points.map(point=>({date:new Date(point.t),value:point.rate??null})).filter(point=>!isNaN(point.date)&&point.value!==null);if(scored.length<BEST_TIME_MIN_POSTS)return{enough:false,sample:scored.length,windows:{}};const mean=scored.reduce((sum,point)=>sum+point.value,0)/scored.length,buckets={};scored.forEach(point=>{const day=point.date.getDay(),hour=point.date.getHours();buckets[day]??={};buckets[day][hour]??={sum:0,n:0};buckets[day][hour].sum+=point.value;buckets[day][hour].n+=1;});const windows={};for(let day=0;day<7;day++){const hours=Object.entries(buckets[day]||{}).map(([hour,{sum,n}])=>({hour:+hour,n,score:(sum+2*mean)/(n+2)})).filter(item=>mean>0&&item.score>mean*1.05).sort((a,b)=>b.score-a.score).slice(0,2).sort((a,b)=>a.hour-b.hour);const merged=[];hours.forEach(item=>{const last=merged[merged.length-1];if(last&&last.end===item.hour){last.end+=1;last.posts+=item.n;last.lift=Math.max(last.lift,item.score/mean);}else merged.push({start:item.hour,end:item.hour+1,posts:item.n,lift:item.score/mean});});windows[day]=merged.map(item=>({...item,lift:Math.round(item.lift*10)/10}));}return{enough:true,sample:scored.length,windows};}
const STARTER_WINDOWS={0:[{start:10,end:12}],1:[{start:9,end:11},{start:12,end:13}],2:[{start:9,end:11},{start:12,end:13}],3:[{start:9,end:11},{start:12,end:13}],4:[{start:9,end:11},{start:12,end:13}],5:[{start:9,end:11}],6:[{start:10,end:12}]};
async function loadBestTimes(){const clientId=$('#calendar-client')?.value||'',key=clientId||'all';if(bestTimes.key===key||bestTimes.loading)return;if(!cloudFeaturesAvailable()||currentRole!=='admin'){bestTimes={key,loading:false,points:[],weeks:0,windows:STARTER_WINDOWS,enough:false,sample:0,source:'starter'};renderCalendar();return;}bestTimes={...bestTimes,loading:true};try{const data=await callSocialApi({action:'best-times',clientId}),result=computeBestTimes(data.points||[]);bestTimes={key,loading:false,points:data.points||[],weeks:data.weeks||0,...result,windows:result.enough?result.windows:STARTER_WINDOWS,source:result.enough?'history':'starter'};}catch(error){console.error('Best times failed:',error);bestTimes={key,loading:false,points:[],weeks:0,windows:STARTER_WINDOWS,enough:false,sample:0,source:'starter'};}renderCalendar();}
