function mediaPreviewHtml(preview,media=[]){const item=preview||(media[0]&&{kind:media[0].type?.startsWith('video/')?'video':'image',src:media[0].url,name:media[0].name||'Uploaded media'});if(!item)return '<div class="media-placeholder">▧<small>Your image or video will appear here</small></div>';return item.kind==='image'?`<img src="${escapeHtml(item.src)}" alt="Uploaded preview" style="width:100%;height:100%;object-fit:cover">`:`<div class="media-placeholder">▶<small>${escapeHtml(item.name)}</small></div>`;}
function activeEditor(){return activeVariant==='all'?$('#post-copy'):$('#variant-copy');}
function selectVariant(platform){activeVariant=platform;const custom=platform!=='all';$('#post-copy').hidden=custom;$('#variant-copy').hidden=!custom;if(custom){$('#variant-copy').value=variantFor(platform).text;$('#variant-copy').placeholder=`Write ${platformLabel(platform)}-specific copy…`;}$('#post-copy-label').textContent=custom?`${platformLabel(platform)} copy`:'Post copy';updatePreview();}
function renderVariantTabs(){const tabs=$('#platform-tabs'),note=$('#variant-note');if(!tabs)return;const platforms=selectedPlatforms();tabs.hidden=!platforms.length;tabs.innerHTML=[['all','All platforms','✦'],...platforms.map(platform=>[platform,platformLabel(platform),SOCIAL_NETWORKS.find(item=>item[0]===platform)?.[2]||'•'])].map(([platform,label,icon])=>{const variant=variantFor(platform),limit=PLATFORM_CHAR_LIMITS[platform],over=platform!=='all'&&limit&&variant.text.length>limit,custom=variant.customText||variant.customMedia;return `<button type="button" role="tab" class="platform-tab ${platform===activeVariant?'active':''} ${over?'over-limit':''}" data-variant="${platform}" aria-selected="${platform===activeVariant}" title="${over?'Over character limit':custom?'Customized':'Using shared content'}"><span class="platform-icon ${platform}">${icon}</span>${escapeHtml(label)}${custom?'<i class="variant-dot"></i>':''}</button>`;}).join('');if(!note)return;note.hidden=activeVariant==='all';if(activeVariant==='all')return;const variant=variantFor(activeVariant),label=platformLabel(activeVariant);$('#variant-note-text').textContent=`${label} uses ${variant.customText?'custom copy':'the shared copy'} and ${variant.customMedia?'custom media':'shared media'}. Changes here only affect ${label}.`;$('#reset-variant').hidden=!variant.customText&&!variant.customMedia;}
