function insertAtCursor(el,text){const start=el.selectionStart,end=el.selectionEnd;el.value=el.value.slice(0,start)+text+el.value.slice(end);el.focus();el.selectionStart=el.selectionEnd=start+text.length;el.dispatchEvent(new Event('input',{bubbles:true}));}
$('#upload-zone')?.addEventListener('click',()=>$('#media-input').click());
$('#media-input')?.addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(!file.type.startsWith('image/')&&!file.type.startsWith('video/')){toast('Choose an image or video file.');return;}if(file.size>50*1024*1024){toast('Media must be 50 MB or smaller.');return;}const target=activeVariant,preview={kind:file.type.startsWith('image/')?'image':'video',src:URL.createObjectURL(file),name:file.name};if(target==='all'){uploadedMedia=[];sharedMediaPreview=preview;}else platformOverrides[target]={...platformOverrides[target],media:[],preview};updatePreview();if(!supabaseClient||!activeUser){scheduleDraftSave();toast('Local preview only. Sign in and configure storage to publish media.');return;}const extension=(file.name.match(/\.([a-z0-9]{1,8})$/i)?.[1]||'bin').toLowerCase(),path=`${activeUser.id}/${crypto.randomUUID()}.${extension}`;try{const{error}=await supabaseClient.storage.from('social-media').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(error)throw error;const{data}=supabaseClient.storage.from('social-media').getPublicUrl(path),media={path,url:data.publicUrl,name:file.name,type:file.type};if(target==='all'){if(sharedMediaPreview===preview)uploadedMedia=[media];}else if(platformOverrides[target]?.preview===preview)platformOverrides[target].media=[media];scheduleDraftSave();toast(target==='all'?'Media uploaded and ready to publish.':`${platformLabel(target)} media uploaded.`);}catch(error){console.error('Media upload failed:',error);toast('Media preview loaded, but upload failed. Check Supabase Storage setup.');}});
const FOLLOWUP_DELAYS=[[15,'15 minutes'],[60,'1 hour'],[180,'3 hours'],[360,'6 hours'],[720,'12 hours'],[1440,'1 day'],[2880,'2 days'],[10080,'1 week']];
const PRIVACY_CHOICES={linkedin:[['','Default (public)'],['public','Public'],['connections','Connections only'],['loggedin','Signed-in LinkedIn members']],youtube:[['','Default (private)'],['public','Public'],['unlisted','Unlisted'],['private','Private']],tiktok:[['','Default (public)'],['public','Public'],['followers','Followers (private accounts only)'],['friends','Friends'],['private','Only me']]};
function defaultPostOptions(){return{collaborators:'',tags:'',visibility:{},firstComment:'',followUps:[],repost:{enabled:false,repeat:2,days:7}};}
let postOptions=defaultPostOptions(),privacyPlatformsKey=null;
function normalizePostOptions(value){if(!value||typeof value!=='object')return defaultPostOptions();return{collaborators:typeof value.collaborators==='string'?value.collaborators:'',tags:typeof value.tags==='string'?value.tags:'',visibility:Object.fromEntries(Object.entries(value.visibility||{}).filter(([platform,choice])=>choice&&PRIVACY_CHOICES[platform]?.some(([key])=>key===choice))),firstComment:typeof value.firstComment==='string'?value.firstComment:'',followUps:Array.isArray(value.followUps)?value.followUps.filter(item=>item&&typeof item.comment==='string').slice(0,5).map(item=>({comment:item.comment,delayMinutes:FOLLOWUP_DELAYS.some(([minutes])=>minutes===item.delayMinutes)?item.delayMinutes:60})):[],repost:{enabled:value.repost?.enabled===true,repeat:Math.min(10,Math.max(1,parseInt(value.repost?.repeat)||2)),days:Math.min(365,Math.max(2,parseInt(value.repost?.days)||7))}};}
function usernameList(value){return value.split(/[\s,]+/).map(name=>name.trim().replace(/^@/,'')).filter(Boolean);}
function renderPostOptionInputs(){if(!$('#post-options'))return;$('#ig-collaborators').value=postOptions.collaborators;$('#ig-tags').value=postOptions.tags;$('#first-comment').value=postOptions.firstComment;$('#reshare-enabled').checked=postOptions.repost.enabled;$('#reshare-repeat').value=postOptions.repost.repeat;$('#reshare-days').value=postOptions.repost.days;renderFollowUps();privacyPlatformsKey=null;renderPostOptionAvailability();}
function renderFollowUps(){$('#followup-list').innerHTML=postOptions.followUps.map((item,index)=>`<div class="followup-row" data-followup="${index}"><textarea class="field option-textarea" data-followup-comment aria-label="Follow-up comment ${index+1}" placeholder="Comment text">${escapeHtml(item.comment)}</textarea><select class="field" data-followup-delay aria-label="When to post follow-up comment ${index+1}">${FOLLOWUP_DELAYS.map(([minutes,label])=>`<option value="${minutes}" ${minutes===item.delayMinutes?'selected':''}>${label} after</option>`).join('')}</select><button type="button" class="icon-button" data-remove-followup title="Remove comment">×</button></div>`).join('');$('#add-followup').hidden=postOptions.followUps.length>=5;}
function renderPostOptionAvailability(){if(!$('#post-options'))return;const platforms=selectedPlatforms(),instagram=platforms.includes('instagram'),privacyPlatforms=platforms.filter(platform=>PRIVACY_CHOICES[platform]),key=privacyPlatforms.join(',');$('#instagram-people').hidden=!instagram;$('#people-unavailable').hidden=instagram;if(key!==privacyPlatformsKey){privacyPlatformsKey=key;$('#privacy-fields').innerHTML=privacyPlatforms.map(platform=>`<label class="field-label" for="privacy-${platform}">${escapeHtml(platformLabel(platform))}</label><select id="privacy-${platform}" class="field" data-privacy="${platform}">${PRIVACY_CHOICES[platform].map(([value,label])=>`<option value="${value}" ${(postOptions.visibility[platform]||'')===value?'selected':''}>${label}</option>`).join('')}</select>`).join('')+`<p class="option-hint">${privacyPlatforms.length?'':'Select LinkedIn, YouTube, or TikTok to set who can see the post. '}Facebook and Instagram posts follow the page or account’s own audience settings.</p>`;}$('#reshare-fields').hidden=!postOptions.repost.enabled;$('#tiktok-comment-hint').hidden=!(platforms.includes('tiktok')&&postOptions.firstComment.trim()&&(postOptions.visibility.tiktok||'public')!=='public');updatePostOptionSummaries(platforms);renderChecklist();}
function updatePostOptionSummaries(platforms){const collaborators=usernameList(postOptions.collaborators).length,tags=usernameList(postOptions.tags).length,privacy=Object.entries(postOptions.visibility).filter(([platform])=>platforms.includes(platform)),followUps=postOptions.followUps.filter(item=>item.comment.trim()).length;$('#people-summary').textContent=platforms.includes('instagram')&&(collaborators||tags)?[collaborators&&`${collaborators} collaborator${collaborators===1?'':'s'}`,tags&&`${tags} tag${tags===1?'':'s'}`].filter(Boolean).join(' · '):'None';$('#privacy-summary').textContent=privacy.length?privacy.map(([platform,value])=>`${platformLabel(platform)}: ${PRIVACY_CHOICES[platform].find(([choice])=>choice===value)[1]}`).join(' · '):'Network default';$('#comments-summary').textContent=[postOptions.firstComment.trim()&&'First comment',followUps&&`${followUps} follow-up${followUps===1?'':'s'}`].filter(Boolean).join(' + ')||'None';$('#reshare-summary').textContent=postOptions.repost.enabled?`${postOptions.repost.repeat}× every ${postOptions.repost.days} days`:'Off';}
function buildPostOptionsPayload(platforms){const options={};if(platforms.includes('instagram')){const collaborators=usernameList(postOptions.collaborators),tags=usernameList(postOptions.tags),invalid=[...collaborators,...tags].find(name=>!/^[A-Za-z0-9._]{1,30}$/.test(name));if(invalid){toast(`“${invalid}” isn’t a valid Instagram username.`);return null;}if(collaborators.length>3){toast('Instagram allows up to 3 collaborators.');return null;}if(collaborators.length)options.collaborators=collaborators;if(tags.length){const variant=variantFor('instagram'),kind=variant.preview?.kind||(variant.media[0]?.type?.startsWith('video/')?'video':'image');options.userTags=tags.map((username,index)=>kind==='image'?{username,x:Math.round((index+1)/(tags.length+1)*100)/100,y:0.9}:{username});}}const visibility=Object.fromEntries(Object.entries(postOptions.visibility).filter(([platform])=>platforms.includes(platform)));if(Object.keys(visibility).length)options.visibility=visibility;if(postOptions.firstComment.trim())options.firstComment=postOptions.firstComment.trim();const followUps=postOptions.followUps.filter(item=>item.comment.trim()).map(item=>({comment:item.comment.trim(),delayMinutes:item.delayMinutes}));if(followUps.length)options.followUpComments=followUps;if(postOptions.repost.enabled)options.autoRepost={repeat:postOptions.repost.repeat,days:postOptions.repost.days};return options;}
$('#post-options')?.addEventListener('input',e=>{const target=e.target;if(target.id==='ig-collaborators')postOptions.collaborators=target.value;else if(target.id==='ig-tags')postOptions.tags=target.value;else if(target.id==='first-comment')postOptions.firstComment=target.value;else if(target.id==='reshare-repeat')postOptions.repost.repeat=Math.min(10,Math.max(1,parseInt(target.value)||1));else if(target.id==='reshare-days')postOptions.repost.days=Math.min(365,Math.max(2,parseInt(target.value)||2));else if(target.matches('[data-followup-comment]'))postOptions.followUps[+target.closest('[data-followup]').dataset.followup].comment=target.value;else return;renderPostOptionAvailability();scheduleDraftSave();});
$('#post-options')?.addEventListener('change',e=>{const target=e.target;if(target.id==='reshare-enabled')postOptions.repost.enabled=target.checked;else if(target.matches('[data-privacy]')){if(target.value)postOptions.visibility[target.dataset.privacy]=target.value;else delete postOptions.visibility[target.dataset.privacy];}else if(target.matches('[data-followup-delay]'))postOptions.followUps[+target.closest('[data-followup]').dataset.followup].delayMinutes=+target.value;else if(target.id==='reshare-repeat'||target.id==='reshare-days'){target.value=target.id==='reshare-repeat'?postOptions.repost.repeat:postOptions.repost.days;return;}else return;renderPostOptionAvailability();scheduleDraftSave();});
$('#post-options')?.addEventListener('click',e=>{const remove=e.target.closest('[data-remove-followup]');if(e.target.closest('#add-followup')){if(postOptions.followUps.length>=5)return;postOptions.followUps.push({comment:'',delayMinutes:60});renderFollowUps();$$('#followup-list [data-followup-comment]').pop()?.focus();}else if(remove){postOptions.followUps.splice(+remove.closest('[data-followup]').dataset.followup,1);renderFollowUps();}else return;renderPostOptionAvailability();scheduleDraftSave();});
function savePost(status,providerResponse=null){const copy=$('#post-copy').value.trim();if(!copy){toast('Add post copy before saving.');$('#post-copy').focus();return;}const client=$('#client-select').value,clientWorkspace=clients.find(item=>item.name===client),date=$('#schedule-date').value||'2026-10-19',time=$('#schedule-time').value||'10:00',channel=$$('.account-select input[type=checkbox]:checked').map(input=>input.value).join(', ')||'Social',initials=client.split(' ').map(word=>word[0]).join('').slice(0,2),providerPost=providerResponse?.posts?.[0]||providerResponse,providerPostId=providerPost?.id||providerResponse?.id||'',providerPostIds=providerResponse?.posts?providerResponse.posts.map(item=>item.id).filter(Boolean):providerPostId?[providerPostId]:[],platformContent=Object.fromEntries(selectedPlatforms().filter(platform=>platformOverrides[platform]).map(platform=>{const variant=variantFor(platform);return[platform,{text:variant.text,mediaUrls:variant.media.map(media=>media.url)}];}));const post={id:crypto.randomUUID(),day:new Date(date+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}).toUpperCase(),time:new Date(`2000-01-01T${time}`).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),client,initials,color:client==='Bright School Kits'?'coral':client==='Revere Rum'?'gold':client==='STEM Story Kits'?'green-bg':'blue-bg',title:copy.split('\n')[0].slice(0,75),channel,status,date,providerPostId,providerPostIds,platformContent,providerUrl:providerPost?.postIds?.[0]?.postUrl||'',cls:client==='Bright School Kits'?'event-coral':client==='Revere Rum'?'event-gold':client==='STEM Story Kits'?'event-green':'event-purple'};savedPosts.unshift(post);renderUpcoming();renderCalendar();if(status==='In Review'){approvals.unshift({id:post.id,title:post.title,client,clientId:clientWorkspace?.id,channel,by:activeUser?.email||'You',status:'In Review',initials,color:post.color,providerPostId,providerPostIds});renderApprovals();}toast(status==='Scheduled'?'Post scheduled through connected accounts.':status==='In Review'?'Post sent to the provider approval queue.':'Draft saved in this browser.');}
