const workspaceStorageKey='signaldesk-workspace-v1';
const supabaseConfig=window.SIGNALDESK_CONFIG||{};
const supabaseConfigured=Boolean(supabaseConfig.url&&supabaseConfig.anonKey);
const supabaseClient=supabaseConfigured&&window.supabase?.createClient?window.supabase.createClient(supabaseConfig.url,supabaseConfig.anonKey):null;
let activeUser=null;
let workspaceSaveTimer;
function setStorageStatus(message){const label=$('#storage-status-label');if(label)label.textContent=message;}
let currentRole='admin',activeWorkspace=null,sharedStateDirty=false;
const USER_VIEWS=new Set(['overview','composer','library']);
function canView(name){return currentRole==='admin'||USER_VIEWS.has(name);}
function applyRole(){const admin=currentRole==='admin';$$('[data-view]').forEach(el=>{el.hidden=!canView(el.dataset.view);});[$('.nav-label.spaced'),$('.help-card'),$('.approval-panel')].forEach(el=>{if(el)el.hidden=!admin;});$('#schedule-post').hidden=!admin;const submit=$('#submit-review');submit.textContent=admin?'Send for approval':'Submit for approval';submit.classList.toggle('primary-button',!admin);submit.classList.toggle('secondary-button',admin);$('#role-note').hidden=admin;$('#profile-name').textContent=activeUser?.email||'Workspace Admin';$('#profile-role').textContent=admin?'Admin access':'User access';const active=$('.page.active')?.id?.replace('view-','');if(active&&!canView(active))showView('overview');}
function collectSettings(){const fields=$$('.settings-form .field');return{name:fields[0]?.value||'PK Works Studio',timezone:fields[1]?.value||'Eastern Time (US & Canada)',approval:fields[2]?.value||'Require approval before publishing'};}
function collectSharedState(){return{clients,savedPosts,approvals,settings:collectSettings()};}
function collectDraftState(){return{uploadedMedia,draft:$('#post-copy')?.value||'',draftOverrides:Object.fromEntries(Object.entries(platformOverrides).map(([platform,{preview,...override}])=>[platform,override])),postOptions};}
function collectWorkspaceState(){return{...collectSharedState(),...collectDraftState()};}
function applyWorkspaceState(state={}){if(Array.isArray(state.clients))clients.splice(0,clients.length,...state.clients.map(client=>({...client,id:client.id||`client-${client.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}`})));if(Array.isArray(state.savedPosts))savedPosts=state.savedPosts;if(Array.isArray(state.approvals))approvals.splice(0,approvals.length,...state.approvals);const fields=$$('.settings-form .field'),settings=state.settings||{};if(fields[0])fields[0].value=settings.name||'PK Works Studio';if(fields[1])fields[1].value=settings.timezone||'Eastern Time (US & Canada)';if(fields[2])fields[2].value=settings.approval||'Require approval before publishing';renderClientSelects();}
function applyDraftState(state={}){const validMedia=media=>media&&typeof media.path==='string'&&typeof media.url==='string'&&media.url.startsWith('https://');uploadedMedia=Array.isArray(state.uploadedMedia)?state.uploadedMedia.filter(validMedia):[];sharedMediaPreview=null;if($('#post-copy'))$('#post-copy').value=typeof state.draft==='string'?state.draft:'';platformOverrides=Object.fromEntries(Object.entries(state.draftOverrides&&typeof state.draftOverrides==='object'?state.draftOverrides:{}).filter(([platform])=>SOCIAL_NETWORKS.some(item=>item[0]===platform)).map(([platform,override])=>[platform,{...(typeof override?.text==='string'?{text:override.text}:{}),...(Array.isArray(override?.media)?{media:override.media.filter(validMedia)}:{})}]));postOptions=normalizePostOptions(state.postOptions);renderPostOptionInputs();}
// Team members share one state row, so saves merge with the latest copy instead of overwriting it.
function stateItemKey(item){return item.id||[item.title,item.date||'',item.client,item.channel].join('|');}
function mergeStateList(remote,local,pick=(remoteItem,localItem)=>localItem){if(!Array.isArray(remote))return local;const localKeys=new Set(local.map(stateItemKey)),remoteByKey=new Map(remote.map(item=>[stateItemKey(item),item]));return[...remote.filter(item=>!localKeys.has(stateItemKey(item))),...local.map(item=>remoteByKey.has(stateItemKey(item))?pick(remoteByKey.get(stateItemKey(item)),item):item)];}
function mergeSharedState(remote={},local){const admin=currentRole==='admin',{draft,draftOverrides,uploadedMedia:legacyMedia,postOptions:legacyOptions,...shared}=remote;return{...shared,clients:admin?mergeStateList(remote.clients,local.clients):remote.clients,settings:admin?local.settings:remote.settings,savedPosts:mergeStateList(remote.savedPosts,local.savedPosts),approvals:mergeStateList(remote.approvals,local.approvals,(remoteItem,localItem)=>remoteItem.status==='Approved'?remoteItem:localItem)};}
function queueSave(showToast){clearTimeout(workspaceSaveTimer);workspaceSaveTimer=setTimeout(()=>saveWorkspaceState(showToast),350);}
function scheduleWorkspaceSave(showToast=false){sharedStateDirty=true;queueSave(showToast);}
function scheduleDraftSave(){queueSave(false);}
async function saveWorkspaceState(showToast=false){const saveShared=sharedStateDirty;sharedStateDirty=false;try{if(supabaseConfigured){if(!activeUser||!activeWorkspace){setStorageStatus('Sign in to sync');return;}if(!supabaseClient)throw new Error('Supabase SDK failed to load');const now=new Date().toISOString();const{error:draftError}=await supabaseClient.from('user_drafts').upsert({user_id:activeUser.id,workspace_id:activeWorkspace.id,draft:collectDraftState(),updated_at:now});if(draftError)throw draftError;if(saveShared){const{data,error:readError}=await supabaseClient.from('workspace_state').select('state').eq('workspace_id',activeWorkspace.id).maybeSingle();if(readError)throw readError;const merged=mergeSharedState(data?.state||{},collectSharedState());const{error}=await supabaseClient.from('workspace_state').update({state:merged,updated_by:activeUser.id,updated_at:now}).eq('workspace_id',activeWorkspace.id);if(error)throw error;applyWorkspaceState(merged);renderUpcoming();renderApprovals();}setStorageStatus('Cloud synced');}else{localStorage.setItem(workspaceStorageKey,JSON.stringify(collectWorkspaceState()));setStorageStatus('Saved in browser');}if(showToast)toast('Workspace settings saved.');}catch(error){if(saveShared)sharedStateDirty=true;console.error('Workspace save failed:',error);setStorageStatus('Save failed');toast(error.message?.includes('Only workspace admins')?error.message:'Could not save workspace changes. Check your connection and setup.');}}
