async function publishSocialPost(requiresApproval=false){const client=selectedClient('#client-select'),text=$('#post-copy').value.trim(),platforms=selectedPlatforms();if(!client||!platforms.length){toast('Choose a client and at least one connected account.');return;}const missingCopy=platforms.find(platform=>!variantFor(platform).text.trim());if(missingCopy){toast(`Add post copy for ${platformLabel(missingCopy)} before publishing.`);selectVariant(platformOverrides[missingCopy]?.text!==undefined?missingCopy:'all');activeEditor().focus();return;}const platformContent=Object.fromEntries(platforms.filter(platform=>platformOverrides[platform]).map(platform=>{const variant=variantFor(platform),content={};if(variant.customText)content.text=variant.text.trim();if(variant.customMedia)content.mediaUrls=variant.media.map(media=>media.url);return[platform,content];}));const options=buildPostOptionsPayload(platforms);if(!options)return;const date=$('#schedule-date').value,time=$('#schedule-time').value;let scheduleDate;try{scheduleDate=new Date(`${date}T${time}`).toISOString();}catch{toast('Choose a valid schedule date and time.');return;}try{const result=await callSocialApi({action:'publish',clientId:client.id,text,platforms,mediaUrls:uploadedMedia.map(media=>media.url),platformContent,options,scheduleDate,requiresApproval:requiresApproval||currentRole!=='admin'});const outcomes=result.postIds||result.posts?.flatMap(item=>item.postIds||[])||[];if(result.status==='error'||(outcomes.length&&outcomes.every(item=>item.status==='error')))throw new Error(result.errors?.[0]?.message||'The provider could not publish to the selected networks.');const held=result.requiresApproval??requiresApproval,queued=result.queuedComments?` with ${result.queuedComments} follow-up comment${result.queuedComments===1?'':'s'} queued`:'';savePost(held?'In Review':'Scheduled',result);scheduleWorkspaceSave();if(result.status==='partial'){const failed=result.errors.flatMap(item=>item.platforms||[]).map(platformLabel).join(', ');toast(`Published to some networks, but ${failed} failed: ${result.errors[0]?.message||'provider error'}`);return;}toast(held?`Post submitted for admin approval${queued}.`:`Post scheduled${queued}.`);}catch(error){toast(error.message);}}
