async function postSocialComment(){const postId=$('#comment-post-id')?.value.trim(),comment=$('#post-comment-text')?.value.trim(),client=selectedClient('#live-inbox-client-select');if(!postId||!comment||!client){toast('Select a client, enter a post ID, and write a comment.');return;}try{await callSocialApi({action:'post-comment',clientId:client.id,postId,comment,platform:$('#comment-platform').value});$('#post-comment-text').value='';toast('Comment posted.');await loadSocialComments();}catch(error){toast(error.message);}}
const WEEKDAYS=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const AUTOPILOT_IMAGE_PLATFORMS=new Set(['instagram','pinterest','tiktok']);
let autopilotData={feeds:[],items:[],comments:[]},editingFeedId=null;
function cloudFeaturesAvailable(){return Boolean(activeUser&&supabaseConfigured&&supabaseClient);}
function localIsoDate(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function autopilotCalendarEvents(){return autopilotData.items.filter(item=>item.scheduled_for&&['scheduled','in_review'].includes(item.status)).map(item=>{const when=new Date(item.scheduled_for),feed=autopilotData.feeds.find(candidate=>candidate.id===item.feed_id),client=clients.find(candidate=>candidate.id===feed?.client_id);return{date:localIsoDate(when),minutes:when.getHours()*60+when.getMinutes(),channel:(item.platforms||feed?.platforms||[]).map(platformLabel).join(', '),time:when.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),title:item.title||'Autopilot post',client:client?.name||'Autopilot',status:item.status,autopilot:true,cls:item.status==='in_review'?'event-autopilot pending':'event-autopilot'};});}
function formatFeedTime(time){const[hour,minute]=time.split(':').map(Number);return new Date(2000,0,1,hour,minute).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});}
function describeFeedDays(days){const sorted=[...days].sort((a,b)=>a-b);const key=sorted.join();return key==='1,2,3,4,5'?'Weekdays':key==='0,6'?'Weekends':sorted.length===7?'Every day':sorted.map(day=>WEEKDAYS[day]).join(', ');}
async function loadAutopilot(){const status=$('#autopilot-status');if(!cloudFeaturesAvailable()){if(status)status.textContent='Sign in with cloud sync and the social API configured to connect RSS feeds.';renderFeeds();return;}if(currentRole!=='admin')return;if(status)status.textContent='Loading Autopilot…';try{autopilotData=await callSocialApi({action:'autopilot'});renderFeeds();renderCalendar();renderApprovals();}catch(error){if(status)status.textContent=error.message;}}
function renderFeeds(){const list=$('#feed-list'),status=$('#autopilot-status');if(!list)return;const feeds=autopilotData.feeds,upcoming=autopilotData.items.filter(item=>['scheduled','in_review'].includes(item.status)&&Date.parse(item.scheduled_for)>Date.now()),pendingComments=autopilotData.comments.filter(item=>item.status==='pending').length,active=feeds.filter(feed=>feed.enabled).length;if(status&&cloudFeaturesAvailable())status.textContent=feeds.length?`${active} active feed${active===1?'':'s'} · ${upcoming.length} upcoming Autopilot post${upcoming.length===1?'':'s'}${pendingComments?` · ${pendingComments} scheduled comment${pendingComments===1?'':'s'} waiting`:''}`:'No feeds yet. Connect one to start filling the calendar.';list.innerHTML=feeds.map(feed=>{const client=clients.find(candidate=>candidate.id===feed.client_id),count=upcoming.filter(item=>item.feed_id===feed.id).length,failed=autopilotData.items.filter(item=>item.feed_id===feed.id&&item.status==='failed').length;return `<div class="feed-card ${feed.enabled?'':'paused'}"><div class="feed-card-main"><b>${escapeHtml(feed.feed_title||feed.url)}</b><small>${escapeHtml(feed.url)}</small><div class="feed-meta"><span>${escapeHtml(client?.name||'Unknown client')}</span><span class="feed-icons">${feed.platforms.map(platform=>`<i class="platform-icon ${platform}" title="${escapeHtml(platformLabel(platform))}">${SOCIAL_NETWORKS.find(item=>item[0]===platform)?.[2]||'•'}</i>`).join('')}</span><span>${describeFeedDays(feed.days)} · ${feed.times.map(formatFeedTime).join(', ')}</span><span class="status ${feed.mode==='review'?'review':'scheduled'}">${feed.mode==='review'?'Approval queue':'Auto-schedule'}</span>${feed.enabled?'':'<span class="status draft">Paused</span>'}</div><small class="feed-health ${feed.last_error?'has-error':''}">${feed.last_error?`⚠ ${escapeHtml(feed.last_error)}`:feed.last_checked_at?`Checked ${new Date(feed.last_checked_at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`:'Not checked yet'} · ${count} upcoming${failed?` · ${failed} failed`:''}</small></div><div class="feed-actions"><button type="button" class="secondary-button" data-feed-toggle="${feed.id}">${feed.enabled?'Pause':'Resume'}</button><button type="button" class="secondary-button" data-feed-edit="${feed.id}">Edit</button><button type="button" class="text-button" data-feed-delete="${feed.id}">Remove</button></div></div>`;}).join('');}
function feedTimesHtml(times){return times.map(time=>`<div class="feed-time"><input type="time" class="field" value="${escapeHtml(time)}" required aria-label="Posting time"><button type="button" class="icon-button" data-remove-time title="Remove time">×</button></div>`).join('');}
async function renderFeedPlatforms(selected=[]){const box=$('#feed-platforms'),client=clients.find(candidate=>candidate.id===$('#feed-client').value);if(!client){box.innerHTML='';return;}box.innerHTML='<p class="account-empty">Loading connected accounts…</p>';try{const accounts=socialAccountCache.get(client.id)||(await callSocialApi({action:'accounts',clientId:client.id})).accounts||[];socialAccountCache.set(client.id,accounts);const linked=accounts.filter(account=>account.linked&&account.platform!=='youtube');box.innerHTML=linked.length?linked.map(account=>{const network=SOCIAL_NETWORKS.find(item=>item[0]===account.platform);return `<label class="account-choice"><input type="checkbox" value="${account.platform}" ${selected.includes(account.platform)?'checked':''}><span class="platform-icon ${account.platform}">${network?.[2]||'•'}</span><span><b>${escapeHtml(network?.[1]||account.platform)}</b><small>${AUTOPILOT_IMAGE_PLATFORMS.has(account.platform)?'Only posts articles with an image':escapeHtml(account.displayName||account.username||client.name)}</small></span></label>`;}).join(''):'<p class="account-empty">No social accounts are linked for this client yet. Connect them in Social Accounts.</p>';}catch(error){box.innerHTML=`<p class="account-empty">${escapeHtml(error.message)}</p>`;}}
function openFeedForm(feed=null){if(!cloudFeaturesAvailable()){toast('Sign in with cloud sync and the social API configured to connect RSS feeds.');return;}editingFeedId=feed?.id||null;const form=$('#feed-form'),select=$('#feed-client');form.hidden=false;$('#feed-form-title').textContent=feed?'Edit feed':'Connect an RSS feed';select.innerHTML=clients.map(client=>`<option value="${escapeHtml(client.id)}">${escapeHtml(client.name)}</option>`).join('');select.value=feed?.client_id||selectedClient('#client-select')?.id||clients[0]?.id||'';$('#feed-url').value=feed?.url||'';$('#feed-url').readOnly=Boolean(feed);$('#preview-feed').hidden=Boolean(feed);$('#feed-preview').innerHTML='';$('#feed-template').value=feed?.template||'{title}\n\n{link}';$('#feed-days').innerHTML=WEEKDAYS.map((day,index)=>`<label class="day-chip"><input type="checkbox" value="${index}" ${(feed?.days||[1,2,3,4,5]).includes(index)?'checked':''}><span>${day}</span></label>`).join('');$('#feed-times').innerHTML=feedTimesHtml(feed?.times||['09:00']);form.querySelector(`input[name=feed-mode][value=${feed?.mode==='auto'?'auto':'review'}]`).checked=true;$('#feed-image').checked=feed?feed.include_image:true;$('#feed-include').value=feed?.include_keywords||'';$('#feed-exclude').value=feed?.exclude_keywords||'';$('#feed-latest').checked=false;$('#feed-latest-row').hidden=Boolean(feed);$('#feed-latest-hint').hidden=Boolean(feed);renderFeedPlatforms(feed?.platforms||[]);form.scrollIntoView({behavior:'smooth',block:'start'});}
function feedToInput(feed,patch={}){return{id:feed.id,clientId:feed.client_id,platforms:feed.platforms,template:feed.template,days:feed.days,times:feed.times,mode:feed.mode,includeImage:feed.include_image,includeKeywords:feed.include_keywords,excludeKeywords:feed.exclude_keywords,enabled:feed.enabled,...patch};}
