$('#preview-feed')?.addEventListener('click',async()=>{const url=$('#feed-url').value.trim(),box=$('#feed-preview');if(!url){toast('Enter a feed URL first.');return;}box.textContent='Reading feed…';try{const data=await callSocialApi({action:'feed-preview',url});box.innerHTML=`<b>${escapeHtml(data.title||'Latest articles')}</b>${data.items.map(item=>`<div class="feed-preview-item">${item.image?`<img src="${escapeHtml(item.image)}" alt="">`:'<span class="feed-preview-noimg">▧</span>'}<div><span>${escapeHtml(item.title||item.link)}</span><small>${item.publishedAt?new Date(item.publishedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'No date'}${item.image?'':' · no image'}</small></div></div>`).join('')}`;}catch(error){box.textContent=error.message;}});
$('#feed-form')?.addEventListener('submit',async e=>{e.preventDefault();const feed=feedFormValues();if(!feed.platforms.length){toast('Choose at least one network.');return;}if(!feed.days.length){toast('Choose at least one posting day.');return;}if(!feed.times.length){toast('Add a posting time.');return;}const button=$('#save-feed');button.disabled=true;try{const result=await callSocialApi({action:'feed-save',feed,queueLatest:!editingFeedId&&$('#feed-latest').checked});$('#feed-form').hidden=true;editingFeedId=null;toast(result.run?.error?`Feed saved, but the first check failed: ${result.run.error}`:result.run?.created?'Feed connected and the latest article was queued.':'Feed saved. New articles are queued as they’re published.');await loadAutopilot();}catch(error){toast(error.message);}finally{button.disabled=false;}});
$('#feed-list')?.addEventListener('click',async e=>{const toggle=e.target.closest('[data-feed-toggle]'),edit=e.target.closest('[data-feed-edit]'),remove=e.target.closest('[data-feed-delete]'),id=toggle?.dataset.feedToggle||edit?.dataset.feedEdit||remove?.dataset.feedDelete,feed=autopilotData.feeds.find(item=>item.id===id);if(!feed)return;if(edit){openFeedForm(feed);return;}try{if(toggle){await callSocialApi({action:'feed-save',feed:feedToInput(feed,{enabled:!feed.enabled})});toast(feed.enabled?'Feed paused.':'Feed resumed.');}else{if(!confirm(`Remove “${feed.feed_title||feed.url}”? Posts it already created stay scheduled with the provider.`))return;await callSocialApi({action:'feed-delete',id:feed.id});toast('Feed removed.');}await loadAutopilot();}catch(error){toast(error.message);}});
$('#run-autopilot')?.addEventListener('click',async()=>{if(!cloudFeaturesAvailable()){toast('Sign in with cloud sync and the social API configured to run Autopilot.');return;}const button=$('#run-autopilot');button.disabled=true;try{const result=await callSocialApi({action:'autopilot-run'}),created=result.feeds.reduce((sum,feed)=>sum+(feed.created||0),0),errors=result.feeds.filter(feed=>feed.error).length;toast(`${created} new post${created===1?'':'s'} queued${errors?` · ${errors} feed${errors===1?'':'s'} had errors`:''}${result.comments.posted?` · ${result.comments.posted} scheduled comment${result.comments.posted===1?'':'s'} posted`:''}.`);await loadAutopilot();}catch(error){toast(error.message);}finally{button.disabled=false;}});
async function loadTeam(){const list=$('#team-list'),form=$('#invite-form');if(!list)return;if(!cloudFeaturesAvailable()){list.innerHTML='<p class="account-empty">Sign in with cloud sync configured to invite teammates. Browser-only mode has a single admin.</p>';form.hidden=true;return;}form.hidden=false;list.innerHTML='<p class="account-empty">Loading team…</p>';try{const data=await callSocialApi({action:'members'});list.innerHTML=[...data.members.map(member=>{const self=member.user_id===data.currentUserId;return `<div class="team-row"><div class="contact-avatar lavender">${escapeHtml(member.email.slice(0,2).toUpperCase())}</div><div class="team-person"><b>${escapeHtml(member.email)}</b><small>${self?'You · ':''}Joined ${new Date(member.created_at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</small></div><select class="field" data-member-role="${member.user_id}" aria-label="Role for ${escapeHtml(member.email)}"><option value="admin" ${member.role==='admin'?'selected':''}>Admin</option><option value="user" ${member.role==='user'?'selected':''}>User</option></select>${self?'<span></span>':`<button type="button" class="text-button" data-member-remove="${member.user_id}">Remove</button>`}</div>`;}),...data.invites.map(invite=>`<div class="team-row invited"><div class="contact-avatar">✉</div><div class="team-person"><b>${escapeHtml(invite.email)}</b><small>Invited as ${invite.role==='admin'?'Admin':'User'} · waiting for sign-up</small></div><span class="status review">Invited</span><button type="button" class="text-button" data-invite-remove="${escapeHtml(invite.email)}">Revoke</button></div>`)].join('');}catch(error){list.innerHTML=`<p class="account-empty">${escapeHtml(error.message)}</p>`;}}
