$('#team-list')?.addEventListener('change',async e=>{const select=e.target.closest('[data-member-role]');if(!select)return;try{await callSocialApi({action:'update-member',userId:select.dataset.memberRole,role:select.value});toast('Role updated.');if(select.dataset.memberRole===activeUser?.id){location.reload();return;}}catch(error){toast(error.message);}loadTeam();});
$('#team-list')?.addEventListener('click',async e=>{const member=e.target.closest('[data-member-remove]'),invite=e.target.closest('[data-invite-remove]');if(!member&&!invite)return;try{if(member){if(!confirm('Remove this person from the workspace? They lose access right away.'))return;await callSocialApi({action:'remove-member',userId:member.dataset.memberRemove});toast('Member removed.');}else{await callSocialApi({action:'remove-invite',email:invite.dataset.inviteRemove});toast('Invite revoked.');}loadTeam();}catch(error){toast(error.message);}});
function renderGreeting(){const now=new Date(),hour=now.getHours(),eyebrow=$('#today-eyebrow'),greeting=$('#greeting');if(eyebrow)eyebrow.textContent=now.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase();if(greeting)greeting.textContent=hour<12?'Good morning.':hour<17?'Good afternoon.':'Good evening.';}
function timeAgo(iso){const seconds=Math.max(0,(Date.now()-Date.parse(iso))/1000);if(seconds<60)return 'just now';const minutes=seconds/60;if(minutes<60)return `${Math.floor(minutes)}m ago`;const hours=minutes/60;if(hours<24)return `${Math.floor(hours)}h ago`;const days=hours/24;return days<7?`${Math.floor(days)}d ago`:new Date(iso).toLocaleDateString('en-US',{month:'short',day:'numeric'});}
const NOTIFICATION_ICONS={approvals:'✓',autopilot:'⚡',reports:'▤',team:'♧',publishing:'!'};
let notificationItems=[],notificationTimer=null;
function startNotifications(){clearInterval(notificationTimer);renderNotifications();if(!cloudFeaturesAvailable())return;loadNotifications();notificationTimer=setInterval(()=>{if(!document.hidden)loadNotifications();},60000);}
async function loadNotifications(){if(!cloudFeaturesAvailable())return;const{data,error}=await supabaseClient.from('notifications').select('id,type,category,title,body,view,read_at,created_at').eq('user_id',activeUser.id).order('created_at',{ascending:false}).limit(30);if(error){console.error('Notifications failed to load:',error);return;}notificationItems=data||[];renderNotifications();}
function renderNotifications(){const list=$('#notifications-list'),count=$('#notification-count');if(!list)return;const unread=notificationItems.filter(item=>!item.read_at).length;count.hidden=!unread;count.textContent=unread>9?'9+':String(unread);$('#notifications-button').setAttribute('aria-label',unread?`Notifications, ${unread} unread`:'Notifications');$('#mark-all-read').hidden=!unread;if(!cloudFeaturesAvailable()){list.innerHTML='<p class="account-empty">Sign in with cloud sync to get notifications.</p>';return;}list.innerHTML=notificationItems.length?notificationItems.map(item=>`<button type="button" class="notification-item ${item.read_at?'':'unread'}" data-notification="${escapeHtml(item.id)}"><span class="notification-icon ${escapeHtml(item.category)}" aria-hidden="true">${NOTIFICATION_ICONS[item.category]||'•'}</span><span class="notification-copy"><b>${escapeHtml(item.title)}</b>${item.body?`<span>${escapeHtml(item.body)}</span>`:''}<small>${timeAgo(item.created_at)}${item.read_at?'':' · New'}</small></span></button>`).join(''):'<p class="account-empty">You’re all caught up.</p>';}
async function markNotificationsRead(ids){if(!ids.length||!cloudFeaturesAvailable())return;const now=new Date().toISOString();notificationItems.forEach(item=>{if(ids.includes(item.id))item.read_at=item.read_at||now;});renderNotifications();const{error}=await supabaseClient.from('notifications').update({read_at:now}).in('id',ids);if(error)console.error('Could not mark notifications read:',error);}
function toggleNotifications(open){const panel=$('#notifications-panel'),button=$('#notifications-button');if(!panel)return;const show=open??panel.hidden;panel.hidden=!show;button.setAttribute('aria-expanded',String(show));if(show)loadNotifications();}
$('#notifications-button')?.addEventListener('click',e=>{e.stopPropagation();toggleNotifications();});
document.addEventListener('click',e=>{if($('#notifications-panel')&&!$('#notifications-panel').hidden&&!e.target.closest('.notifications-wrap'))toggleNotifications(false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#notifications-panel')&&!$('#notifications-panel').hidden){toggleNotifications(false);$('#notifications-button').focus();}});
$('#notifications-list')?.addEventListener('click',e=>{const button=e.target.closest('[data-notification]');if(!button)return;const item=notificationItems.find(candidate=>candidate.id===button.dataset.notification);markNotificationsRead([button.dataset.notification]);toggleNotifications(false);if(item?.view&&viewNames[item.view])showView(item.view);});
$('#mark-all-read')?.addEventListener('click',()=>markNotificationsRead(notificationItems.filter(item=>!item.read_at).map(item=>item.id)));
async function openNotificationPreferences(){toggleNotifications(false);const dialog=$('#notification-dialog'),message=$('#notification-message'),save=$('#save-notification-prefs');message.textContent='';save.disabled=!cloudFeaturesAvailable();if(!dialog.open)dialog.showModal();if(!cloudFeaturesAvailable()){message.textContent='Sign in with cloud sync to choose notification preferences.';return;}try{const[{data,error},status]=await Promise.all([supabaseClient.from('notification_preferences').select('email_frequency,email_categories,weekly_day').eq('user_id',activeUser.id).maybeSingle(),callSocialApi({action:'notification-settings'}).catch(()=>null)]);if(error)throw error;const prefs={email_frequency:'daily',email_categories:['approvals','autopilot','reports','team','publishing'],weekly_day:1,...(data||{})},frequency=$(`#notification-form input[name=email-frequency][value="${prefs.email_frequency}"]`);if(frequency)frequency.checked=true;$('#weekly-day').value=String(prefs.weekly_day);$$('#notification-form input[name=email-category]').forEach(input=>{input.checked=prefs.email_categories.includes(input.value);});if(status&&!status.emailConfigured)message.textContent='Email delivery isn’t set up for this workspace yet, so only in-app notifications arrive for now.';}catch(error){message.textContent=error.message;}}
