$('#notification-form')?.addEventListener('submit',async e=>{e.preventDefault();if(!cloudFeaturesAvailable())return;const frequency=$('#notification-form input[name=email-frequency]:checked')?.value||'daily',categories=$$('#notification-form input[name=email-category]:checked').map(input=>input.value),button=$('#save-notification-prefs');button.disabled=true;const{error}=await supabaseClient.from('notification_preferences').upsert({user_id:activeUser.id,workspace_id:activeWorkspace?.id||null,email_frequency:frequency,email_categories:categories,weekly_day:+$('#weekly-day').value,updated_at:new Date().toISOString()});button.disabled=false;if(error){$('#notification-message').textContent=error.message;return;}$('#notification-dialog').close();toast(frequency==='off'?'Email notifications turned off. You’ll still see them under the bell.':'Notification preferences saved.');});
const TOP_POST_COLUMNS=[['views','Views'],['reach','Reach'],['engagements','Engagement'],['engagementRate','Eng. rate'],['likes','Likes'],['comments','Comments'],['shares','Shares'],['saves','Saves'],['clicks','Clicks'],['videoViews','Video views'],['watchMinutes','Watch time (min)'],['avgWatchSeconds','Avg. watch (s)']];
let topPostsReport=null,topPostsStarted=false;
function recentWeekStarts(count=8){const today=new Date();today.setHours(0,0,0,0);const monday=new Date(today);monday.setDate(today.getDate()-((today.getDay()+6)%7));return Array.from({length:count},(_,index)=>{const start=new Date(monday);start.setDate(monday.getDate()-7*(index+1));return start;});}
function initTopPosts(){const clientSelect=$('#top-posts-client');if(!clientSelect)return;const selected=clientSelect.value;clientSelect.innerHTML=clients.map(client=>`<option value="${escapeHtml(client.id)}">${escapeHtml(client.name)}</option>`).join('');if(clients.some(client=>client.id===selected))clientSelect.value=selected;const week=$('#top-posts-week');if(!week.options.length){const starts=recentWeekStarts();week.innerHTML='<option value="last7">Last 7 days</option>'+starts.map(start=>{const end=new Date(start);end.setDate(start.getDate()+6);return `<option value="${localIsoDate(start)}">Week of ${start.toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${end.toLocaleDateString('en-US',{month:'short',day:'numeric'})}</option>`;}).join('');week.value=localIsoDate(starts[0]);}if(!topPostsStarted){topPostsStarted=true;loadTopPosts();}}
async function loadTopPosts(refresh=false){const status=$('#top-posts-status');if(!cloudFeaturesAvailable()){status.textContent='Sign in and connect client accounts to see Top Posts.';topPostsReport=null;renderTopPosts();return;}const clientId=$('#top-posts-client').value;if(!clientId)return;status.textContent='Gathering post metrics… busy accounts can take a minute.';$('#refresh-top-posts').disabled=true;try{const result=await callSocialApi({action:'top-posts',clientId,range:$('#top-posts-week').value,refresh});topPostsReport=result.report;const missing=topPostsReport.errors?.length;status.textContent=`${topPostsReport.postCount} published post${topPostsReport.postCount===1?'':'s'} · updated ${timeAgo(topPostsReport.generatedAt)}${missing?` · metrics unavailable for ${missing}`:''}`;}catch(error){topPostsReport=null;status.textContent=error.message;}finally{$('#refresh-top-posts').disabled=false;}renderTopPosts();}
function formatMetric(key,value){if(value===null||value===undefined)return '—';if(key==='engagementRate')return `${value.toFixed(value<10?2:1)}%`;if(value>=10000)return `${(value/1000).toFixed(value>=100000?0:1)}k`;return value.toLocaleString('en-US',{maximumFractionDigits:1});}
