$('#trends-body')?.addEventListener('click',e=>{const tagButton=e.target.closest('[data-use-hashtag]'),ideaButton=e.target.closest('[data-trend-idea]'),copy=$('#post-copy');if(tagButton){const tag=tagButton.dataset.useHashtag;copy.value=`${copy.value.trimEnd()} ${tag}`.trim();copy.dispatchEvent(new Event('input',{bubbles:true}));toast(`${tag} added to your draft.`);}else if(ideaButton){const idea=trendReport?.data.ideas[+ideaButton.dataset.trendIdea];if(!idea)return;const text=`${idea.hook}\n\n${idea.description}`;copy.value=copy.value.trim()?`${copy.value.trimEnd()}\n\n${text}`:text;showView('composer');selectVariant('all');copy.dispatchEvent(new Event('input',{bubbles:true}));toast('Idea added to your draft in Publishing Studio.');}});
