const platformIssues=platformChecks(),errors=platformIssues.filter(issue=>issue.level==='error'),warnings=platformIssues.filter(issue=>issue.level==='warn'),platformSummary=platforms.length?`<p class="check-detail">Posting as <b>${escapeHtml(client)}</b> to ${escapeHtml(platforms.map(platformLabel).join(', '))}.</p>`:'';
items.push(checkItem(!platforms.length?'pending':errors.length?'fail':warnings.length?'warn':'done',!platforms.length?'Right platforms':errors.length?`Right platforms — ${errors.length} problem${errors.length===1?'':'s'}`:warnings.length?'Right platforms — check notes':'Right platforms and formats',platformSummary+(platformIssues.length?`<ul class="check-list">${platformIssues.map(issue=>`<li class="${issue.level}"><b>${escapeHtml(issue.label)}:</b> ${escapeHtml(issue.message)}</li>`).join('')}</ul>`:''),true));
const links=texts.flatMap(item=>extractLinks(item.text)).filter((url,index,list)=>list.indexOf(url)===index),results=links.map(url=>({url,...(linkResults.get(url)||{status:cloudFeaturesAvailable()?'checking':'unchecked'})})),broken=results.filter(item=>item.status==='broken'),unknown=results.filter(item=>item.status==='unknown'),checking=results.filter(item=>item.status==='checking'),linkList=list=>`<ul class="check-list">${list.map(item=>`<li class="${item.status==='broken'?'error':item.status==='unknown'?'warn':''}"><a href="${escapeHtml(item.url)}" target="_blank" rel="noopener">${escapeHtml(item.url.replace(/^https?:\/\//,'').slice(0,60))}</a>${item.detail?` <small>${escapeHtml(item.detail)}</small>`:''}</li>`).join('')}</ul>`;
